 cid=s['contrast'];g=rd(T/(cid+'.OBSERVED_GENE_SCORES.tsv')).set_index('gene');v=rd(O/(cid+'.GUIDE_QL.tsv.gz'));v['positive_rank']=(-v.standardized_effect).rank(method='average')/(len(v)+1);v['negative_rank']=v.standardized_effect.rank(method='average')/(len(v)+1);rr=[];gg=[]
